arguments.command:
cd /tmp/opencode && python3 - <<'PY'
import csv, json
from datetime import date
AUDIT=date(2026,3,31)
def pd(s):
    if not s or s=="none": return None
    y,m,d=s.split("-"); return date(int(y),int(m),int(d))
lic={}
for r in csv.DictReader(open("/app/input/licensed_property_register.csv")):
    lic[r["license_id"]]=dict(r, valid_until=pd(r["valid_until"]),
        max_character_area_pct=None if r["max_character_area_pct"]=="none" else float(r["max_character_area_pct"]))
succ={row["supersedes"]:lid for lid,row in lic.items() if row["supersedes"]!="none"}
def gov(lid):
    c=lid
    while c in succ: c=succ[c]
    return lic[c]
acc={}
for r in csv.DictReader(open("/app/input/client_accounts.csv")): acc[r["account_id"]]=r
reqs=list(csv.DictReader(open("/app/input/composite_request_log.csv")))
RO=["UNLICENSED_CHARACTER_USE","THIRD_PARTY_BACKGROUND_UNLICENSED","MISSING_MINOR_CONSENT","COMMERCIAL_DISTRIBUTION_FLAG","ALTERATION_DISCLOSURE_MISSING"]
def dc(cov,d): return True if cov=="all" else d in cov.split(";")
def ev(r):
    f=[]; d=r["intended_distribution"]
    if r["character_property"]!="none":
        if d!="personal_only":
            lid=r["character_license_id"]; cov=False; cap=None
            if lid!="none" and lid in lic:
                g=gov(lid)
                if g["license_type"]=="character" and dc(g["covers_distribution"],d) and g["valid_until"] and g["valid_until"]>=AUDIT:
                    cov=True; cap=g["max_character_area_pct"]
            if not cov: f.append(RO[0])
            elif cap is not None and float(r["character_px_area"])/float(r["canvas_px_area"])*100>cap: f.append(RO[0])
    bs=r["background_source"]
    if bs=="third_party_unlicensed": f.append(RO[1])
    elif bs=="third_party_licensed":
        lid=r["background_license_id"]; cov=False
        if lid!="none" and lid in lic:
            g=gov(lid)
            if g["license_type"]=="background" and dc(g["covers_distribution"],d) and g["valid_until"] and g["valid_until"]>=AUDIT: cov=True
        if not cov: f.append(RO[1])
    if r["subject_is_minor"]=="True":
        ct=r["minor_consent_type"]; pres=ct!="none"; cur=pd(r["minor_consent_valid_until"]) and pd(r["minor_consent_valid_until"])>=AUDIT
        wide = True if ct=="publicity" else (ct=="basic" and d in ("personal_only","client_internal"))
        if not(pres and cur and wide): f.append(RO[2])
    if d in ("social_public","print_for_sale"):
        a=acc[r["account_id"]]; cl=(a["agreement_status"]=="active" and dc(a["master_agreement_covers"],d))
        if not cl: f.append(RO[3])
    if r["alteration_level"]=="substantive" and d in ("social_public","print_for_sale") and r["alteration_disclosure_on_file"]!="True": f.append(RO[4])
    return [x for x in RO if x in f]
aud=[r for r in reqs if r["intake_status"]!="withdrawn"]
comp={}
for r in aud: comp[r["request_id"]]=ev(r)
# compare audit CSV
csvrows=[(r[0],r[1]) for r in list(csv.reader(open("/app/composite_request_audit.csv")))[1:]]
exp=[]
for r in sorted(aud,key=lambda x:int(x["request_id"].split("-")[1])):
    fs=comp[r["request_id"]]
    exp.append((r["request_id"],"none")) if not fs else exp.extend((r["request_id"],x) for x in fs)
assert csvrows==exp, "AUDIT CSV MISMATCH:\n"+str([(c,e) for c,e in zip(csvrows,exp) if c!=e])
print("audit CSV: exact match (",len(csvrows),"rows )")
# compare account summary
asum={r[0]:r for r in list(csv.reader(open("/app/account_summary.csv")))[1:]}
bf=sum(1 for k in comp if comp[k]); bt=len(comp); bs=bf/bt
esc_n=0
for a in sorted(acc,key=lambda x:int(x.split("-")[1])):
    rids=[k for k in comp if [r for r in aud if r["request_id"]==k][0]["account_id"]==a]
    cnt=len(rids); fl=sum(1 for k in rids if comp[k]); mx=max((len(comp[k]) for k in rids),default=0)
    e = (fl/cnt if cnt else 0)>bs or mx>=3
    row=asum[a]
    assert row[1]==acc[a]["account_type"] and int(row[2])==cnt and int(row[3])==fl and (row[4]=="ESCALATION_REQUIRED")==(e), a
    esc_n+=e
    assert (row[4]=="ESCALATION_REQUIRED")==e, (a,row)
print("account_summary: exact match; escalated =",esc_n)
# results.json
fig=json.load(open("/app/results.json"))
def co(c): return sum(1 for k in comp if c in comp[k])
exp_fig={"request_count":bt,"account_count":sum(1 for a in acc if any(r["account_id"]==a for r in aud)),
 "flagged_count":bf,"compliant_count":bt-bf,"finding_total":sum(len(comp[k]) for k in comp),
 "character_count":co(RO[0]),"background_count":co(RO[1]),"consent_count":co(RO[2]),
 "commercial_count":co(RO[3]),"disclosure_count":co(RO[4]),"escalated_accounts":esc_n}
assert fig==exp_fig, ("JSON MISMATCH",fig,exp_fig)
print("results.json: exact match")
print("\nALL DELIVERABLES VERIFIED")
PY

